<script setup lang="ts">
definePageMeta({layout:'workspace'})
type House={id:string;name:string;colour:string|null}
type Entry={student_id:string;house_id:string|null;year_level:string|null;students:{given_name:string;family_name:string;is_active:boolean}|null}
const db=useSupabaseClient(),{schoolId,schoolRole,platformAdmin}=useSchool()
const canManage=computed(()=>platformAdmin.value||schoolRole.value==='school_admin')
const houses=ref<House[]>([]),entries=ref<Entry[]>([]),year=ref(new Date().getFullYear()),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const selected=ref<House|null>(null),dialog=ref(false),editing=ref(false),confirm=ref(false)
const form=reactive({name:'',colour:'#2563eb'})
const active=computed(()=>entries.value.filter(e=>e.students?.is_active))
const count=(id:string)=>active.value.filter(e=>e.house_id===id).length
const unassigned=computed(()=>active.value.filter(e=>!e.house_id).length)
const filtered=computed(()=>houses.value.filter(h=>h.name.toLowerCase().includes(search.value.toLowerCase())))
const roster=computed(()=>active.value.filter(e=>e.house_id===selected.value?.id).sort((a,b)=>(a.students?.family_name||'').localeCompare(b.students?.family_name||'')))
async function load(){if(!schoolId.value){houses.value=[];entries.value=[];return}loading.value=true;error.value='';try{
const [h,e]=await Promise.all([db.from('school_houses').select('id,name,colour').eq('school_id',schoolId.value).order('name'),db.from('student_enrolments').select('student_id,house_id,year_level,students(given_name,family_name,is_active)').eq('school_id',schoolId.value).eq('school_year',year.value)])
if(h.error||e.error)throw h.error||e.error
houses.value=(h.data||[]) as House[];entries.value=(e.data||[]) as unknown as Entry[]
}catch(e:any){error.value=e.message||'Unable to load houses'}finally{loading.value=false}}
function view(h:House){selected.value=h;editing.value=false;dialog.value=true}
function add(){selected.value=null;Object.assign(form,{name:'',colour:'#2563eb'});editing.value=true;dialog.value=true}
function edit(){if(!canManage.value)return;Object.assign(form,{name:selected.value?.name||'',colour:selected.value?.colour||'#2563eb'});editing.value=true}
function cancel(){confirm.value=false;if(selected.value){editing.value=false}else dialog.value=false}
async function save(){if(!canManage.value||busy.value)return;confirm.value=false;busy.value=true;error.value='';try{
const name=form.name.trim();if(!name)throw new Error('House name is required')
if(houses.value.some(h=>h.id!==selected.value?.id&&h.name.toLowerCase()===name.toLowerCase()))throw new Error('House name already exists')
const payload={name,colour:form.colour}
const r=selected.value?await db.from('school_houses').update(payload).eq('school_id',schoolId.value).eq('id',selected.value.id).select('id').single():await db.from('school_houses').insert({...payload,school_id:schoolId.value}).select('id').single()
if(r.error)throw r.error;await load();selected.value=houses.value.find(h=>h.id===r.data.id)||null;editing.value=false;notice.value='House saved successfully'
}catch(e:any){error.value=e.message||'Unable to save house'}finally{busy.value=false}}
watch([schoolId,year],()=>{dialog.value=false;void load()},{immediate:true})
</script>
<template><div class="space-y-6">
<div class="flex flex-wrap items-stretch justify-end gap-3"><div class="flex flex-1 flex-wrap items-stretch justify-end gap-2"><div v-for="m in [{label:'Total houses',value:houses.length},{label:'Assigned students',value:active.length-unassigned},{label:'Unassigned',value:unassigned}]" :key="m.label" class="flex min-w-[115px] flex-1 items-center justify-between gap-3 rounded-xl border border-[var(--border)] bg-[var(--panel)] px-4 py-2.5 sm:max-w-[190px]"><span class="text-xs text-[var(--muted)]">{{m.label}}</span><strong class="text-xl">{{m.value}}</strong></div></div><button v-if="canManage" class="rounded-xl bg-blue-600 px-5 font-semibold text-white" @click="add">+ Add house</button></div>
<p v-if="error" role="alert" class="rounded-xl bg-red-50 p-4 text-red-700">{{error}}</p><p v-if="notice" role="status" class="text-sm text-green-700">{{notice}}</p>
<UiPanel><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">House directory</h2><label class="text-sm">School year <input v-model.number="year" type="number" min="2000" max="2100" class="ml-2 w-24 rounded-lg border border-[var(--border)] bg-[var(--surface)] p-2"/></label></div><input v-model="search" aria-label="Search houses" placeholder="Search houses" class="mb-4 w-full max-w-md rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/><p v-if="loading">Loading houses…</p><div v-else class="overflow-x-auto"><table class="w-full min-w-[450px] text-left text-sm"><thead><tr class="border-b border-[var(--border)] text-[var(--muted)]"><th class="py-3">House</th><th class="p-3">Colour</th><th class="p-3">Active students</th><th class="p-3">Action</th></tr></thead><tbody><tr v-for="h in filtered" :key="h.id" class="border-b border-[var(--border)]"><td class="py-4 font-semibold">{{h.name}}</td><td class="p-3"><span class="inline-flex items-center gap-2"><span class="h-5 w-5 rounded-full" :style="{backgroundColor:h.colour||'#64748b'}"/>{{h.colour||'Not set'}}</span></td><td class="p-3">{{count(h.id)}}</td><td class="p-3"><button :aria-label="'View '+h.name" class="rounded-lg border border-[var(--border)] p-2 text-blue-600" @click="view(h)"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="2" width="18" height="20" rx="2"/><circle cx="12" cy="10" r="3"/><path d="M7 18a5 5 0 0 1 10 0"/></svg></button></td></tr></tbody></table><p v-if="!filtered.length" class="py-8 text-center text-[var(--muted)]">No matching houses.</p></div></UiPanel>
<div v-if="dialog" class="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4"><section role="dialog" aria-modal="true" aria-label="House details" class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><header class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">{{!selected?'Add house':editing?'Edit house':'House details'}}</h2><div class="flex gap-2"><button v-if="selected&&!editing&&canManage" aria-label="Edit house" class="rounded-lg border border-[var(--border)] p-2 text-blue-600" @click="edit">✎</button><button aria-label="Close" @click="dialog=false">✕</button></div></header>
<div v-if="selected&&!editing" class="space-y-4"><div class="grid gap-4 sm:grid-cols-2"><div class="rounded-xl bg-[var(--panel)] p-4"><p class="text-xs text-[var(--muted)]">Name</p><strong>{{selected.name}}</strong></div><div class="rounded-xl bg-[var(--panel)] p-4"><p class="text-xs text-[var(--muted)]">Colour</p><span class="flex items-center gap-2"><span class="h-5 w-5 rounded-full" :style="{backgroundColor:selected.colour||'#64748b'}"/>{{selected.colour||'Not set'}}</span></div></div><h3 class="font-semibold">Students in this house ({{roster.length}})</h3><div class="max-h-64 overflow-y-auto rounded-xl border border-[var(--border)]"><div v-for="e in roster" :key="e.student_id" class="flex justify-between border-b border-[var(--border)] p-3 text-sm"><span>{{e.students?.family_name}}, {{e.students?.given_name}}</span><span>{{e.year_level||'—'}}</span></div><p v-if="!roster.length" class="p-4 text-sm text-[var(--muted)]">No active students assigned this year.</p></div><div class="flex justify-end"><button class="rounded-xl border border-[var(--border)] px-5 py-3" @click="dialog=false">Close</button></div></div>
<form v-else class="space-y-4" @submit.prevent="confirm=true"><label class="block text-sm font-semibold">House name<input v-model="form.name" required maxlength="100" class="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"/></label><label class="block text-sm font-semibold">House colour<div class="mt-1 flex gap-3"><input v-model="form.colour" type="color" class="h-11 w-16"/><input v-model="form.colour" pattern="#[0-9a-fA-F]{6}" required class="rounded-lg border border-[var(--border)] bg-[var(--panel)] p-3"/></div></label><div class="flex justify-end gap-3"><button type="button" class="rounded-xl border border-[var(--border)] px-5 py-3" @click="cancel">Cancel</button><button :disabled="busy" class="rounded-xl bg-blue-600 px-5 py-3 text-white">Save house</button></div></form></section></div>
<div v-if="confirm" class="fixed inset-0 z-[60] grid place-items-center bg-black/65 p-4"><section role="alertdialog" aria-modal="true" class="w-full max-w-sm rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-2xl"><h3 class="text-lg font-bold">Save house?</h3><p class="mt-3">Are you sure you want to {{selected?'update':'add'}} {{form.name}}?</p><div class="mt-6 flex justify-end gap-3"><button class="rounded-xl border border-[var(--border)] px-4 py-2.5" @click="cancel">Cancel</button><button :disabled="busy" class="rounded-xl bg-blue-600 px-4 py-2.5 text-white" @click="save">Yes, save</button></div></section></div>
</div></template>